namespace {
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
struct Fixture {
 MainWindow window;QTableView* view;WorksheetModel* model;
 Fixture(){window.resize(1280,720);window.show();window.activateWindow();QApplication::processEvents();view=window.findChild<QTableView*>("worksheet.grid");model=dynamic_cast<WorksheetModel*>(view->model());}
 void select(int row1,int col1,int row2,int col2){view->setCurrentIndex(model->index(row1,col1));view->selectionModel()->select(QItemSelection(model->index(row1,col1),model->index(row2,col2)),QItemSelectionModel::ClearAndSelect);view->setFocus();}
 void dialog(const std::function<void(QDialog&)>& inspect){std::exception_ptr error;bool visited=false;window.activateWindow();view->setFocus();QApplication::processEvents();QTimer::singleShot(0,[&]{auto* popup=qobject_cast<QDialog*>(QApplication::activeModalWidget());try{require(popup&&popup->objectName()=="formatCells.dialog","Real Ctrl1 opens the native Format Cells dialog");visited=true;QTest::keyRelease(popup,Qt::Key_Control);popup->activateWindow();QApplication::processEvents();auto* tabs=popup->findChild<QTabWidget*>("formatCells.tabs");QTest::mouseClick(tabs->tabBar(),Qt::LeftButton,Qt::NoModifier,tabs->tabBar()->tabRect(3).center());inspect(*popup);}catch(...){error=std::current_exception();if(popup)popup->reject();}});QTest::keyClick(view,Qt::Key_1,Qt::ControlModifier);QTest::keyRelease(view,Qt::Key_Control);require(visited,"Native Format Cells shortcut reached its actual modal");if(error)std::rethrow_exception(error);}
};
QToolButton* preset(QDialog& popup,const char* name){auto* result=popup.findChild<QToolButton*>(QString("formatCells.borderPreset.")+name);require(result&&result->isVisible()&&!result->icon().isNull(),"Source Border page needs graphical, visible None/Outline/Inside preset controls");return result;}
void source(){Fixture f;f.model->setData(f.model->index(15,1),"Pre-Tax Income:",Qt::EditRole);f.model->setData(f.model->index(15,2),"1861",Qt::EditRole);f.select(15,1,15,9);const auto before=f.window.currentSession().snapshotView();f.window.setProperty("formatCells.lastTab",1);
 f.dialog([&](QDialog& popup){auto* none=preset(popup,"none");auto* outline=preset(popup,"outline");preset(popup,"inside");auto* list=popup.findChild<QListWidget*>("formatCells.borderStyleList");auto* color=popup.findChild<QComboBox*>("formatCells.borderColorSelector");auto* preview=popup.findChild<QWidget*>("formatCells.borderPreview");auto* top=popup.findChild<QCheckBox*>("formatCells.border.top");require(list&&list->isVisible()&&list->count()==14&&list->size()==QSize(121,115),"Source Style list contains all fourteen two-column graphical line samples at their measured size");require(color&&color->isVisible()&&color->itemText(color->currentIndex())=="Automatic","Source Color selector starts at Automatic");require(preview&&preview->isVisible()&&preview->size()==QSize(151,98)&&top&&top->isVisible()&&top->size()==QSize(22,21),"Source has the measured live preview and graphical top-edge button");require(top->text().isEmpty()&&!top->icon().isNull()&&!top->isChecked(),"The source edge button uses an icon rather than a text checkbox");for(const auto* edge:{"middleHorizontal","middleVertical","diagonalUp","diagonalDown"})require(popup.findChild<QAbstractButton*>(QString("formatCells.border.")+edge),"All eight graphical source edge commands are represented");const auto empty=preview->grab().toImage();QTest::mouseMove(none,none->rect().center());QApplication::processEvents();QTest::mouseMove(outline,outline->rect().center());QApplication::processEvents();require(preview->grab().toImage()==empty&&f.window.currentSession().snapshotView()==before,"Hovering None then Outline changes no border preview, worksheet or history");QTest::mouseClick(top,Qt::LeftButton,Qt::NoModifier,top->rect().center());QApplication::processEvents();const auto changed=preview->grab().toImage();require(top->isChecked()&&changed!=empty&&changed.pixelColor(20,7)==QColor("#000000")&&changed.pixelColor(20,90)!=QColor("#000000"),"Clicking the graphical Top button draws only the top line in the actual live preview");require(f.window.currentSession().snapshotView()==before,"Top-edge preview is temporary until actual modal acceptance");QTest::keyClick(&popup,Qt::Key_Return);});
 for(int col=1;col<=9;++col)require(f.model->cellStyle(15,col).at("border").at("top")==Json({{"style","thin"},{"color","#000000"}}),"Accepted source top border covers every selected cell");require(f.model->raw(15,1)=="Pre-Tax Income:"&&f.model->raw(15,2)=="1861","Source graphical border editing preserves text and numeric inputs");require(f.window.currentSession().undo(),"Source top border is one undo");require(f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"One undo restores the complete pre-dialog worksheet");
}
void presets(){Fixture f;for(int r=1;r<=2;++r)for(int c=1;c<=2;++c)f.model->setData(f.model->index(r,c),r*10+c,Qt::EditRole);f.select(1,1,2,2);const auto before=f.window.currentSession().snapshotView();
 f.dialog([&](QDialog& popup){QTest::mouseClick(preset(popup,"outline"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});
 for(int r=1;r<=2;++r)for(int c=1;c<=2;++c){const auto b=f.model->cellStyle(r,c).at("border");require(b.contains("top")==bool(r==1)&&b.contains("bottom")==bool(r==2)&&b.contains("left")==bool(c==1)&&b.contains("right")==bool(c==2),"Outline changes only the selected rectangle's perimeter, leaving internal edges empty");}
 const auto outlined=f.window.currentSession().snapshotView();f.dialog([&](QDialog& popup){QTest::mouseClick(preset(popup,"inside"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});
 for(int r=1;r<=2;++r)for(int c=1;c<=2;++c)require(f.model->cellStyle(r,c).at("border").size()==4,"Inside adds the internal row/column edges while preserving the existing outline");require(f.window.currentSession().undo()&&f.window.currentSession().snapshotView().at("sheets")==outlined.at("sheets"),"Inside is one undo and restores the earlier outer perimeter");f.model->refresh();
 f.dialog([&](QDialog& popup){QTest::mouseClick(preset(popup,"none"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});
 for(int r=1;r<=2;++r)for(int c=1;c<=2;++c)require(f.model->cellStyle(r,c).value("border",Json::object()).empty(),"None removes selected borders without replacing cell inputs");require(f.window.currentSession().undo()&&f.window.currentSession().snapshotView().at("sheets")==outlined.at("sheets"),"None is one undo");require(f.window.currentSession().undo()&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"Undoing Outline restores the untouched selected cells");
}
void colorAndCancel(){Fixture f;f.model->setData(f.model->index(0,0),"42",Qt::EditRole);f.select(0,0,0,0);const auto before=f.window.currentSession().snapshotView();
 f.dialog([&](QDialog& popup){preset(popup,"none");auto* color=popup.findChild<QLineEdit*>("formatCells.borderColorInput");require(color&&color->isVisible(),"Native RGB acceptance preparation has a genuinely visible color editor");QTest::keyClick(color,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(color,"#AABBCC");QTest::mouseClick(popup.findChild<QCheckBox*>("formatCells.border.top"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Escape);});require(f.window.currentSession().snapshotView()==before,"Cancel discards native color, preset and edge drafts together");
 f.dialog([&](QDialog& popup){auto* color=popup.findChild<QLineEdit*>("formatCells.borderColorInput");color->setFocus();QTest::keyClick(color,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(color,"#AABBCC");QTest::mouseClick(popup.findChild<QCheckBox*>("formatCells.border.top"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});require(f.model->cellStyle(0,0).at("border").at("top").at("color")=="#aabbcc"&&f.model->raw(0,0)=="42","Accepted native color editor feeds the existing normalized thin-border model contract");require(f.window.currentSession().undo()&&f.window.currentSession().snapshotView().at("sheets")==before.at("sheets"),"Graphical color/top editing remains one undo");
}
void mergeWithoutDataLossWarning(){Fixture f;f.model->setData(f.model->index(0,0),"Keep this value",Qt::EditRole);f.select(0,0,0,1);bool warning=false;QTimer rescue;rescue.setInterval(1);QObject::connect(&rescue,&QTimer::timeout,[&]{if(auto* message=qobject_cast<QMessageBox*>(QApplication::activeModalWidget())){warning=true;message->done(QMessageBox::Yes);}});rescue.start();f.dialog([&](QDialog& popup){QTest::mouseClick(preset(popup,"outline"),Qt::LeftButton);auto* tabs=popup.findChild<QTabWidget*>("formatCells.tabs");QTest::mouseClick(tabs->tabBar(),Qt::LeftButton,Qt::NoModifier,tabs->tabBar()->tabRect(1).center());auto* merge=popup.findChild<QCheckBox*>("formatCells.merge");QTest::mouseClick(merge,Qt::LeftButton,Qt::NoModifier,QPoint(5,merge->height()/2));require(merge->isChecked(),"The genuine native merge-checkbox indicator is checked");QTest::keyClick(&popup,Qt::Key_Return);});rescue.stop();require(!warning,"Adding border operations must not turn a lossless merge into a data-loss warning");require(f.model->raw(0,0)=="Keep this value"&&f.window.currentSession().snapshotView().at("sheets")[0].at("mergedRanges").size()==1,"Lossless merge and graphical Outline apply together");}
void invalidColor(){Fixture f;f.model->setData(f.model->index(0,0),"42",Qt::EditRole);f.select(0,0,0,0);const auto before=f.window.currentSession().snapshotView();f.dialog([&](QDialog& popup){auto* color=popup.findChild<QLineEdit*>("formatCells.borderColorInput");color->setFocus();QTest::keyClick(color,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(color,"bad-color");QTest::mouseClick(popup.findChild<QCheckBox*>("formatCells.border.top"),Qt::LeftButton);QTest::keyClick(&popup,Qt::Key_Return);});require(f.window.currentSession().snapshotView()==before&&!f.window.lastError().isEmpty(),"Malformed visible color input must be rejected atomically instead of silently applying the last valid color");}
void mnemonics(){Fixture f;f.select(1,1,2,2);f.dialog([&](QDialog& popup){preset(popup,"outline");QTest::keyClick(&popup,Qt::Key_O,Qt::AltModifier);QTest::keyRelease(&popup,Qt::Key_Alt);QTest::qWait(150);QTest::keyClick(&popup,Qt::Key_Return);});require(f.model->cellStyle(1,1).value("border",Json::object()).contains("top")&&f.model->cellStyle(2,2).value("border",Json::object()).contains("bottom"),"The source-underlined Outline mnemonic invokes the genuine preset before acceptance");}
}
int main(int argc,char** argv){QApplication app(argc,argv);QTemporaryDir state;qputenv("TIGERSHEETS_STATE_DIR",state.path().toUtf8());try{const std::string test=argc>1?argv[1]:"source";if(test=="presets")presets();else if(test=="color")colorAndCancel();else if(test=="merge")mergeWithoutDataLossWarning();else if(test=="invalid")invalidColor();else if(test=="mnemonics")mnemonics();else source();std::cout<<"Native source Border page passed\n";}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
